<?php $pageTitle='Café & Menu';require_once __DIR__.'/../includes/header.php';require_once __DIR__.'/../includes/sidebar.php';requireRole(['owner','manager','cashier','operator']);$db=getDB();$club=$_SESSION['club_id'];if($_SERVER['REQUEST_METHOD']==='POST'){verifyCsrf();$name=sanitize($_POST['name']??'');$price=filter_var($_POST['price']??'',FILTER_VALIDATE_FLOAT);if($name&&$price!==false){$db->prepare('INSERT INTO cafe_items(club_id,name,category,price,stock_quantity,low_stock_threshold) VALUES(?,?,?,?,?,?)')->execute([$club,$name,sanitize($_POST['category']??'Other'),$price,max(0,(int)$_POST['stock_quantity']),max(0,(int)$_POST['low_stock_threshold'])]);$flash='Menu item added.';}else{$flash='Enter a name and valid price.';$error=true;}}$q=$db->prepare('SELECT * FROM cafe_items WHERE club_id=? ORDER BY category,name');$q->execute([$club]);$items=$q->fetchAll();?><div class="flex justify-between"><div><h1 class="text-2xl font-bold">Café & Menu</h1><p class="text-slate-400 text-sm mt-1">Manage available items and stock levels.</p></div></div><?php if(isset($flash)):?><p class="mt-4 <?=$error??false?'text-red-300':'text-green-300'?>"><?=sanitize($flash)?></p><?php endif?><form method="post" class="card mt-5"><input type="hidden" name="csrf_token" value="<?=csrfToken()?>"><div class="grid md:grid-cols-5 gap-3"><input class="input" name="name" placeholder="Item name" required><input class="input" name="category" placeholder="Drinks / Food" required><input class="input" type="number" min="0" step=".01" name="price" placeholder="Price" required><input class="input" type="number" min="0" name="stock_quantity" placeholder="Initial stock" value="0"><input class="input" type="number" min="0" name="low_stock_threshold" placeholder="Low stock" value="0"></div><button class="btn-primary mt-4">Add Menu Item</button></form><section class="grid md:grid-cols-2 xl:grid-cols-3 gap-4 mt-5"><?php foreach($items as $i):?><article class="card"><div class="flex justify-between"><div><span class="text-xs text-slate-400 uppercase"><?=sanitize($i['category'])?></span><h2 class="font-bold text-lg mt-1"><?=sanitize($i['name'])?></h2></div><b class="text-green-400"><?=money($i['price'])?></b></div><div class="mt-5 flex justify-between text-sm"><span class="text-slate-400">Stock: <?=$i['stock_quantity']?></span><span class="<?=$i['stock_quantity']<=$i['low_stock_threshold']?'text-amber-300':'text-green-400'?>"><?=$i['stock_quantity']<=$i['low_stock_threshold']?'Low stock':'Available'?></span></div></article><?php endforeach?></section><?php require __DIR__.'/../includes/footer.php'; ?>
